dd798de2cef1b3576b3adc444\",\"entry_name\":\"Hilo Benioff Medical Center\",\"exam_terms\":[\"brain\",\"70551\"],\"id\":\"dir-74-mri-0\",\"included\":\"Provider-linked cash estimates exclude radiologist/physician/professional fees; additional services may be charged. Cash Price was selected despite a generic insurer-price label. Exact eligibility and total need verification. No rate-effective date shown. These are facility-only estimates, excluded from fixed-price coverage.\",\"mod\":\"MRI\",\"order\":\"Review the facility restrictions below and confirm the exact order requirement.\",\"region\":\"Hilo\",\"scope\":\"Cash Price selection: brain MRI including brain stem, without contrast (CPT 70551), $721.80 estimate; facility component only\",\"type\":\"quote\"}","price_type":"quote"}]$offers$::jsonb;
 item jsonb; before_payload jsonb;
BEGIN
 PERFORM selfpay_directory_sync.check_target();
 LOCK TABLE public.settings,public.entries,public.offers,public.batches,public.publish_events IN SHARE ROW EXCLUSIVE MODE;
 IF (SELECT value FROM public.settings WHERE key='active_batch') IS DISTINCT FROM old_batch THEN RAISE EXCEPTION 'Active batch changed'; END IF;
 IF (SELECT count(*) FROM public.entries WHERE batch_id=old_batch)<>103 OR (SELECT count(*) FROM public.offers WHERE batch_id=old_batch)<>13 THEN RAISE EXCEPTION 'Catalog count changed'; END IF;
 IF selfpay_directory_sync.catalog_fingerprints(old_batch)->>'offer_fingerprint' IS DISTINCT FROM '2a3b5859b77acfcd406614c7d2f3c49d2a4d9877edd2ea4c957067c0956976cd' THEN RAISE EXCEPTION 'Existing offers changed'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(expected) LOOP
  IF NOT EXISTS(SELECT 1 FROM public.entries WHERE batch_id=old_batch AND entry_key=item->>'key' AND content_hash=item->>'hash') THEN RAISE EXCEPTION 'Source entry changed'; END IF;
 END LOOP;
 INSERT INTO public.batches VALUES(new_batch,'23731d5e68e69797bb3d6a2274f253f38bc95d0a91eddd7df397e71013d77c0a','manual-reviewed-mappings-2026-10-09',extract(epoch FROM clock_timestamp()),'staged',$report${"added":103,"added_entries":0,"added_offers":44,"changed":0,"changed_entries":2,"entry_count":103,"id":"58eea4d6-a6da-4559-a9cb-98a7aa2d20d9","located_entries":96,"location_count":130,"mappings_sha256":"1d422bf5861b3b53dafb0b680c414560a8df1872838ff6e6c35f868a26810d5d","new_batch":"395c84be-d26d-5432-bddb-bff7c58c1200","offer_count":57,"preserved_offers":13,"previous_batch":"85c7c95d-a9dd-5533-9427-6fdcefc74ab9","program_count":7,"removed":0,"removed_entries":0,"source_sha256":"103564dd9524c9f8c73c5eaa2378911f78cc285e9570b95945e33456311f2c70","status":"staged","unchanged":false,"unplaced_entries":[],"withheld_offers":[]}$report$);
 INSERT INTO public.entries SELECT new_batch,entry_key,content_hash,payload FROM public.entries WHERE batch_id=old_batch;
 FOR item IN SELECT value FROM jsonb_array_elements(replacements) LOOP
  SELECT payload::jsonb INTO STRICT before_payload FROM public.entries WHERE batch_id=new_batch AND entry_key=item->>'entry_key';
  IF (before_payload-'locations'-'location_type') IS DISTINCT FROM ((item->>'payload')::jsonb-'locations'-'location_type') THEN RAISE EXCEPTION 'Non-geography fields changed'; END IF;
  UPDATE public.entries SET content_hash=item->>'content_hash',payload=item->>'payload' WHERE batch_id=new_batch AND entry_key=item->>'entry_key';
 END LOOP;
 INSERT INTO public.offers SELECT new_batch,id,entry_key,amount_cents,max_cents,price_type,payload FROM public.offers WHERE batch_id=old_batch;
 FOR item IN SELECT value FROM jsonb_array_elements(additions) LOOP
  INSERT INTO public.offers VALUES(new_batch,item->>'id',item->>'entry_key',(item->>'amount_cents')::integer,(item->>'max_cents')::integer,item->>'price_type',item->>'payload');
 END LOOP;
 IF (SELECT count(*) FROM public.entries WHERE batch_id=new_batch)<>103 OR (SELECT count(*) FROM public.offers WHERE batch_id=new_batch)<>57 THEN RAISE EXCEPTION 'Publication count assertion failed'; END IF;
 UPDATE public.batches SET status='published' WHERE id=new_batch;
 UPDATE public.settings SET value=new_batch WHERE key='active_batch' AND value=old_batch;
 IF NOT FOUND THEN RAISE EXCEPTION 'Publication conflict'; END IF;
 INSERT INTO public.publish_events(batch_id,previous_batch,created,action) VALUES(new_batch,old_batch,extract(epoch FROM clock_timestamp()),'publish');
END $publish$;
